Use a circular array with a separate element count. The invariant is `0 ≤ count ≤ 17` and `tail == (head + count) % 17`; when head and tail coincide, count distinguishes empty (`0`) from full (`17`). Rejected operations leave the queue unchanged.

Compile with `g++ -std=c++17 fifo.cpp -o fifo` and run `./fifo`; the tests below keep assertions enabled.

```cpp
#ifdef NDEBUG
#undef NDEBUG
#endif
#include <array>
#include <cassert>
#include <cstddef>
#include <iostream>

class BoundedFifo {
public:
    static constexpr std::size_t capacity = 17;

    bool push(int value) {
        if (count_ == capacity) return false;
        data_[tail_] = value;
        tail_ = (tail_ + 1) % capacity;
        ++count_;
        return true;
    }

    bool pop(int& value) {
        if (count_ == 0) return false;
        value = data_[head_];
        head_ = (head_ + 1) % capacity;
        --count_;
        return true;
    }

    std::size_t size() const { return count_; }
    bool empty() const { return count_ == 0; }
    bool full() const { return count_ == capacity; }

private:
    std::array<int, capacity> data_{};
    std::size_t head_ = 0;
    std::size_t tail_ = 0;
    std::size_t count_ = 0;
};

int main() {
    BoundedFifo queue;
    int value = -1;

    // Empty pop fails without changing the output or queue.
    assert(!queue.pop(value));
    assert(value == -1);
    assert(queue.empty());
    assert(queue.size() == 0);

    // Every slot is usable.
    for (int i = 0; i < 17; ++i) {
        assert(queue.push(i));
        assert(queue.size() == static_cast<std::size_t>(i + 1));
    }
    assert(queue.full());

    // Overflow rejection preserves size and every queued value.
    assert(!queue.push(999));
    assert(queue.size() == 17);
    assert(queue.full());
    for (int i = 0; i < 17; ++i) {
        assert(queue.pop(value));
        assert(value == i);
    }
    assert(queue.empty());
    assert(!queue.pop(value));

    // Refill, remove ten, then append ten across the array boundary.
    for (int i = 0; i < 17; ++i) assert(queue.push(i));
    for (int i = 0; i < 10; ++i) {
        assert(queue.pop(value));
        assert(value == i);
    }
    assert(queue.size() == 7);
    for (int i = 17; i < 27; ++i) assert(queue.push(i));
    assert(queue.full());
    assert(!queue.push(999));

    // Drain across the boundary in FIFO order.
    for (int i = 10; i < 27; ++i) {
        assert(queue.pop(value));
        assert(value == i);
    }
    assert(queue.empty());
    assert(queue.size() == 0);
    assert(!queue.pop(value));

    std::cout << "All tests passed\n";
}
```

The lower median is 4. Copy the array before using `std::nth_element`, so the caller’s array remains unchanged.

The correct zero-based index is `(n - 1) / 2`: for even size `n = 2m`, it is `m - 1`, the lower of the two middle positions; for odd size `n = 2m + 1`, it is `m`, the unique middle position. `std::nth_element` places the value that would occupy that position in sorted order there, including when values repeat.

Compile with `g++ -std=c++17 median.cpp -o median` and run `./median`.

```cpp
#ifdef NDEBUG
#undef NDEBUG
#endif
#include <algorithm>
#include <cassert>
#include <cstddef>
#include <iostream>
#include <stdexcept>
#include <vector>

int lower_median(const std::vector<int>& input) {
    if (input.empty()) {
        throw std::invalid_argument("lower_median requires nonempty input");
    }
    std::vector<int> copy = input;
    const std::size_t index = (copy.size() - 1) / 2;
    auto middle = copy.begin() +
        static_cast<std::vector<int>::difference_type>(index);
    std::nth_element(copy.begin(), middle, copy.end());
    return *middle;
}

int main() {
    const auto check = [](const std::vector<int>& input, int expected) {
        const auto original = input;
        assert(lower_median(input) == expected);
        assert(input == original);
    };

    check({9, 1, 4, 4, 7, 2}, 4); // Duplicates; sorted: 1,2,4,4,7,9.
    check({8, 3, 5, 1, 9}, 5);    // Odd size.
    check({8, 1, 6, 3}, 3);       // Even size: lower middle, not 6.
    check({42}, 42);              // Singleton.
    check({4, 4, 4, 4}, 4);       // All values equal.

    const std::vector<int> empty;
    bool rejected = false;
    try {
        (void)lower_median(empty);
    } catch (const std::invalid_argument&) {
        rejected = true;
    }
    assert(rejected);
    assert(empty.empty());

    std::cout << "All tests passed\n";
    return 0;
}
```

No. A successful retry can store an unchanged value and lose an increment.

Starting at 0: thread A computes `expected=0, desired=1`. Thread B increments the counter to 1. A’s CAS fails, updating `expected` to 1 but leaving `desired` at 1; its retry successfully changes 1 to 1. Both increments finish, but the count is only 1 instead of 2.

Recompute `desired` on every attempt. A spurious failure also retries with a freshly computed desired value, whether or not `expected` changed. Relaxed ordering suffices for this standalone counter; it does not synchronize unrelated data. This unsigned counter wraps modulo 2^64, but the test stays well below that limit.

Compile with `g++ -std=c++17 -O2 -pthread counter.cpp -o counter` and run `./counter`.

```cpp
#ifdef NDEBUG
#undef NDEBUG
#endif
#include <atomic>
#include <cassert>
#include <cstdint>
#include <iostream>
#include <thread>
#include <vector>

void increment(std::atomic<std::uint64_t>& counter) {
    std::uint64_t expected = counter.load(std::memory_order_relaxed);
    for (;;) {
        const std::uint64_t desired = expected + 1;
        if (counter.compare_exchange_weak(
                expected, desired,
                std::memory_order_relaxed,
                std::memory_order_relaxed)) {
            return;
        }
        // Failure, including spurious failure, updates expected.
        // The next iteration recomputes desired from that value.
    }
}

int main() {
    std::atomic<std::uint64_t> counter{0};
    constexpr unsigned thread_count = 4;
    constexpr std::uint64_t increments_per_thread = 100000;
    std::vector<std::thread> threads;
    threads.reserve(thread_count);

    for (unsigned i = 0; i < thread_count; ++i) {
        threads.emplace_back([&counter] {
            for (std::uint64_t j = 0; j < increments_per_thread; ++j) {
                increment(counter);
            }
        });
    }
    for (auto& thread : threads) {
        thread.join();
    }

    const auto final_count = counter.load(std::memory_order_relaxed);
    assert(final_count == thread_count * increments_per_thread);
    std::cout << "All tests passed; final count = " << final_count << '\n';
    return 0;
}
